/* DEC-214: dashboards drawn as treatments to compare for S20 (Bob's direction of October 11, K2803; the research on the
   dashboards page). Three arrangements of Home, then two area dashboards: the three tiers (status, what needs you,
   everything else), whose move it is on every action item, and the five-second and three-step tests. */
/* DEC-216 (Bob's direction, October 13, evening): the home is a nerve center, complete in itself, never only doors to the
   areas; every dashboard keeps the rail of every other screen, collapsed to icons where the room is wanted. DEC-218 (Bob's
   S20, October 14): one home for everyone, arrangement C: what needs you first, then what needs the team, each area at a
   glance, the projects, what changed since you last looked, and the door "What happened?". The areas-first and
   instrument-panel arrangements are set aside; a member's choice among arrangements is held in reserve. */
const AREA_TIPS = {
  Investigation: '<b>Investigation</b> · its dashboard: documents to check, questions and how strong their answers are, the cases they lead to (in review, waiting to be signed, published), what came in since you last looked, the people the record follows',
  Action: '<b>Action</b> · its dashboard: every clock that is running, whose move it is, replies that came in, letters waiting for a second approval',
  Members: '<b>Members</b> · its dashboard: who joined, who is invited, what each may do, expertise on hand',
  Administration: '<b>Administration</b> · its dashboard: the instance and its release, the assistant\'s accounts and their use this month, security, places and translations',
};
const AREA_GO = { Investigation: 'dash-project', Action: 'dash-action', Members: 'members', Administration: 'settings' };
const rd = (n, label) => n === 0 || n === '0' ? '' : `<span class="mk-rd"><b>${n}</b>${esc(label)}</span>`;   // a reading at zero is never shown (DEC-219 (3))
// an area at a glance: its name opens its dashboard; what needs you there; two to four readings; a line or two of state; and, in arrangement A, the items themselves
const ablock = (title, needs, readings, lines, inner) => !needs && !readings.join('') && !lines.length && !inner ? '' : `<div class="mk-ablock"><div class="h">${ref(`<b>${esc(title)}</b>`, AREA_GO[title], AREA_TIPS[title])}<span class="need${needs ? '' : ' quiet'}">${needs || 'nothing needs you here'}</span></div><div class="rd">${readings.join('')}</div>${lines.length ? `<ul class="mk-list mk-small">${lines.map(l => `<li>${l}</li>`).join('')}</ul>` : ''}${inner || ''}</div>`;
const AREA_BLOCKS = () => `<div class="mk-ablocks">${[
  ablock('Investigation', '3 to do', [rd(142, ' documents'), rd(6, ' questions open'), rd(10, ' people followed'), rd(1, ' case')], ['2 questions meet the bar · 1 new this week', 'Edition 2 of the Coliseum case published September 18; a draft is shared for review until October 20, no comment to answer', '7 things came in since you last looked: Dev captured the rent schedules yesterday']),
  ablock('Action', '1 to approve', [rd(3, ' clocks running'), rd(1, ' our move'), rd(2, ' their move')], ['Our move: 1, the earliest due Friday', 'Their move: 2, the earliest due October 9']),
  ablock('Members', '', [rd(6, ' members'), rd(1, ' administrator'), rd(1, ' invited')], ['Expertise on hand: <span class="mk-data">Ana, CPA (confirmed); Teo, reporter (declared)</span>', 'Mai K.\'s invitation link is out, unused']),
  ablock('Administration', '', [rd('0.83.0', ' this release'), rd('ordinary', ' security level')], ['Places: Oakland, California · languages: English, Español'], meter('This month on the team\'s key', 31.40, 60).replace('class="mk-meter"', 'class="mk-meter small"')),
].join('')}</div>`;
const RECENT = sheet(row(I('capture'), 'Dev captured <span class="mk-data">the rent schedules for 2024</span>', '<span class="muted">yesterday</span>') + row(I('timeline'), 'Teo added two events to the Coliseum lease timeline', '<span class="muted">Monday</span>') + row(I('money'), 'Ana started the money trail “Sewer fund transfers, FY2022”', '<span class="muted">3 weeks ago</span>'));
const STRIP = strip([[1, 'of our own dates passed', 'queue', '<b>1 of our own dates passed</b><span class=more>Opens your queue at this item.</span>'], [1, 'due Friday · our move', 'queue', '<b>Decide on the newer lease amendment</b> · due Friday · the team\'s own window<span class=more>Opens your queue at it.</span>'], [1, 'no reply recorded · their move', 'action', '<b>Demand to rescind</b> · the City Administrator\'s reply was due October 9; none recorded<span class=more>Opens the action.</span>'], [2, 'to check', 'queue', '<b>Two checks asked of you</b>: a calculation Ana asked you to check, and 3 photos to vouch for<span class=more>Opens your queue at them.</span>'], [1, 'hint to look at', 'queue', '<b>A hint</b>: a council member\'s disclosed income from a firm whose contract they voted on · machine work, a lead never a finding<span class=more>Opens your queue at it.</span>']]);
const STRIP_NEW = strip([[1, 'no reply recorded · their move', 'action', '<b>Demand to rescind</b> · the City Administrator\'s reply was due October 9; none recorded<span class=more>Opens the action.</span>'], [1, 'due tomorrow · their move', 'request', '<b>Records request</b> · the City Clerk\'s reply is due October 14<span class=more>Opens the request.</span>']]);
const RECORD = tiles(tile('Documents', '142', '+9 this month', [6, 4, 9, 7, 5, 8, 6, 9]), tile('Questions', '6', '2 meet the bar · 1 new', [0, 1, 0, 0, 1, 0, 0, 1]), tile('Cases', '1', 'published · 2 editions', null), tile('People followed', '10', '2 added this month', [1, 0, 0, 1, 0, 0, 1, 1]));
