const ROUTED_REFUSED = (t, ...lines) => `<details class="mk-details"><summary>${t}</summary>${lines.map(x => `<div class="cs-gap" data-gap="refused">${I('refused')}<span>${x}</span></div>`).join('')}</details>`;
