/* B306 A72/A47: the removal arithmetic, drawn once. rows: [how many, takes, who votes, flag]; `now` marks the row that is this team's or project's. */
const ARITH_TABLE = (head, rows, now) => `<div class="tw"><table class="mk-table"><thead><tr><th>${head[0]}</th><th>${head[1]}</th><th>${head[2]}</th></tr></thead><tbody>${rows.map(([n, takes, who]) => `<tr${n === now ? ' aria-current="true"' : ''}><td>${n}${n === now ? ' <b>(now)</b>' : ''}</td><td>${takes}</td><td>${who}</td></tr>`).join('')}</tbody></table></div>`;
const ADMIN_ARITH = [[1, 'not removable', 'no majority that leaves out the one facing removal can be reached'], [2, 'not removable', 'no majority that leaves out the one facing removal can be reached'], [3, '2 of 3', '2 of 3 may vote'], [4, '3 of 4', '3 of 4 may vote'], [5, '3 of 5', '4 of 5 may vote'], [6, '4 of 6', '5 of 6 may vote'], [7, '4 of 7', '6 of 7 may vote']];
const OWNER_ARITH = [[1, 'not removable', 'the last owner stays'], [2, '2 of 2, the departing owner\'s vote included', 'both agree: a resignation the other owner assents to'], [3, '2 of 3', '2 of 3 may vote'], [4, '3 of 4', '3 of 4 may vote'], [5, '3 of 5', '4 of 5 may vote'], [6, '4 of 6', '5 of 6 may vote'], [7, '4 of 7', '6 of 7 may vote']];
