const aiLimitForm = (id, o = {}) => `<div class="row" style="gap:12px;align-items:end;flex-wrap:wrap">${choice(id + 's', 'Limit on', ['Everything (the overall limit)', ...AI_USES.map(u => u[1]), 'Exploring'], 'Everything (the overall limit)', { act: 'ailimitset' })}${field(id + 'a', 'Amount', '', { act: 'ailimitset' })}${choice(id + 'u', 'In', o.signin ? ['tokens', 'calls'] : ['dollars, estimated', 'tokens', 'calls'], 'tokens', { act: 'ailimitset', help: o.signin ? 'A subscription doesn\'t report what a use costs, so its limits are in tokens (the text sent and received) or calls.' : '' })}${choice(id + 'p', 'Per', ['day', 'month'], 'month', { act: 'ailimitset' })}</div>
  <details class="mk-details"><summary>More choices</summary>${checks('For a limit on one use', [['<b>Part of the overall limit</b>: the use counts toward both, and stops at whichever is reached first', true], ['<b>On top of the overall limit</b>: an allowance of its own that doesn\'t count toward the overall one, so this account may spend up to the overall limit plus each allowance on top', false]], { radio: true, act: 'ailimitset' })}</details>
  ${acts(btn('ailimitset', 'Set the limit'))}${note('Your limits bind only your own account; the team\'s and a project\'s limits never bind it. The first time a limit is reached in a period, you are told once in your queue.')}`;
const aiUseOwn = (rows, o = {}) => `<div class="mk-usage"><div><div class="tw"><table class="mk-table"><thead><tr><th>Last 30 days</th><th>Calls</th><th>Tokens</th>${o.signin ? '' : '<th>Dollars, estimated</th>'}</tr></thead><tbody>${rows.map(r => `<tr><td>${r[0]}</td><td class="num">${r[1]}</td><td class="num">${r[2]}</td>${o.signin ? '' : `<td class="num">${r[3]}</td>`}</tr>`).join('')}</tbody></table></div></div><div>${usageBars(o.total || 1.85, o.calls || 26, o.seed || 2)}${(o.meters || []).map(m => meter(...m)).join('')}</div></div>${note('Only you see this: your own use across every account that paid for it. Never a cost per answer.')}`;
const whoPays = `<details class="mk-details"><summary>Which account pays, and when</summary>${note(AI_WHO_PAYS)}</details>`;
