/* DEC-330 (B306, census A9 to A15): shared pieces. A state chip names where an item stands and, on rest or tap, says what that means, what it
   allows and what it rules out (census A11); the same words fill the Glossary. */
const STATE_MEANS = {
  review: ['Awaiting review', "Captured into your team's record and waiting for a member to review it.", 'You can read it and its captured source, mark it reviewed, and revise it; every revision is kept.', 'You cannot publish it: only signed work is published.'],
  reviewed: ['Reviewed', 'A member attested that it appears to be what it claims to be, never that it is accurate.', 'You can cite it from a project, and retire it.', 'You cannot edit it silently: revisions are added and the history is permanent.'],
  retired: ['Retired', 'Withdrawn from use by a member. Kept for good; nothing leaves the record.', 'You can read it and its history.', 'You cannot cite it in new work: projects cite active material.'],
  open: ['Open', 'A question your team is working on. It may rest on nothing yet, because a question worth asking is not a claim.', 'You can gather what it rests on, conclude it, or defer or dismiss it with a reason.', 'You cannot publish it: only a concluded question can be put to anyone.'],
  concluded: ['Concluded', 'A finding: your team has answered the question, named what it rests on, and named what would overturn it.', 'You can read the conclusion, publish it as a case, or reopen it if the answer stops holding.', 'You cannot revise it silently: reopening is recorded, and republishing makes a new edition.'],
  published: ['Published', "A case: signed, public, and checkable by anyone against its published fingerprint without your team's help.", 'You can read it and its editions, and sign a newer edition.', 'You cannot change an edition already signed: a correction is a new edition.'],
  waiting: ['Waiting for a reply', 'Sent to an office that has not replied yet.', 'You can record the reply when it comes, and ask about the silence once the date the law gives has passed.', ''],
  flagged: ['Flagged for a second look', 'A member asked the team to look at this again, with a note saying why.', 'You can read the note, look again, and clear the flag.', ''],
  watched: ['Watched by you', 'On your watch list, so a change to it reaches your queue. Only you see what you watch.', 'You can take it off your list at any time.', ''],
  deferred: ['Deferred', 'Put off by a member of this project, with a reason, to come back to later.', 'You can read it and the reason, and reopen it.', 'You cannot conclude or publish it until it is reopened.'],
  dismissed: ['Dismissed', 'Set aside by a member of this project, with a reason, as not worth pursuing. Nothing is deleted.', 'You can read it and the reason, and reopen it.', 'You cannot conclude or publish it until it is reopened.'],
  divided: ['Divided', 'Split into smaller questions that carry it on. Its own record is closed.', 'You can read it and follow the questions it was divided into.', 'You cannot change it: the questions it was divided into carry the work.'],
  planned: ['Planned', 'Decided on, but not yet under way.', 'You can move it on or abandon it, each with a reason.', ''],
  active: ['Active', 'Under way: it has been sent or begun, and its dates are running.', 'You can record what came back and move it on, each with a reason. Resolving it also says how it ended.', ''],
  resolved: ['Resolved', 'Finished, with the way it ended.', 'You can read it and how it ended.', 'You cannot move it on: it is the end of the action.'],
  abandoned: ['Abandoned', 'Stopped by a member, with a reason, before it ended.', 'You can read it and the reason.', 'You cannot move it on: it is the end of the action.']
};
