// analyst's words, strength R28), what the answer rests on shown back, the readings with their six acts and the reading
// a project stands on (basis-versions R12 to R15; their pair, strength R7, R8), and what relies on the question (backlinks, K960).
const Q_AI412 = ref('Administrative Instruction 4.12', 'document', '<b>Pothole repair policy, Administrative Instruction 4.12</b> · City of Oakland, Public Works · captured from the city&#39;s site September 12, 2026, capture B · current version · cited in 2 questions<span class=why><b>Here:</b> the standard this question tests the city against.</span><span class=more>Click to open it at passage 3.</span>');
const Q_AUDIT = ref('the 2023 audit', 'document', '<b>Public Works performance audit, 2023</b> · City Auditor · captured by Ana, October 5, 2026, capture B<span class=why><b>Here:</b> page 12 counts repairs within seven days, from the same repair log.</span>');
const qFalls = (t, o) => `<span class="mk-small">${I('hint')}If this turned out to be wrong: <b>${t}</b></span>${o ? `<span class="mk-small muted">${o}</span>` : ''}`;
// DEC-245 (K3320): the first investigation's middle and end on the question: new and empty (c), the assistant at work (d), its proposal (e),
// its limit reached (f), concluded (g). Open, cite, run, accept, conclude are screens-inquiry R1, R11, citation R14, ai-runs, run-productions, basis-versions R16 to R20.
// screens-inquiry R23: an answer of "yes" shows the passages to tick; none is preselected, and until saved each passage counts as one the answer can't do without
const QWHICH = 'var w=this.nextElementSibling;if(w)w.hidden=!this.querySelectorAll(\'input\')[1].checked';
const Q_ST = { ask: 'b', new: 'c', running: 'd', proposal: 'e', limit: 'f', concluded: 'g', concludedown: 'h', ended: 'i', stopped: 'j', deferred: 'k', dismissed: 'l' };
/* DEC-293 (screens-inquiry R45, R085): a run that ended without a proposal says why in plain words, never its code, above
   the first step's three ways, the assistant among them. */
/* DEC-288 (the walk's D6, B244): the question page shows where the question stands and the one next step, in three steps:
   bring in a source, mark what it says, say what you conclude; what else can be done is folded. */
const qSteps = cur => `<ol class="mk-steps">${['Bring in a source', 'Mark what it says', 'Say what you conclude'].map((t, i) => `<li${i < cur ? ' class="done"' : ''}${i === cur ? ' aria-current="step"' : ''}>${t}</li>`).join('')}</ol>`;
