const G_W = 860, G_H = 660, G_CX = 430, G_CY = 322, G_R1 = 160, G_R2 = 300, G_NR = 22;
const nodeShape = (k, r) => k === 'person' ? `<circle r="${r}"/>` : k === 'gap' ? `<circle r="${r}" class="gap"/>` : k === 'doc' ? `<path d="M${-r} ${-r * 0.85} h${r * 1.45} l${r * 0.55} ${r * 0.55} v${r * 1.15} h${-2 * r} z"/>` : k === 'pay' ? `<path d="M0 ${-r} L${r} 0 L0 ${r} L${-r} 0 z"/>` : `<rect x="${-r}" y="${-r * 0.78}" width="${2 * r}" height="${1.56 * r}" rx="3"/>`;
const gchip = (x, y, g, scale) => `<g class="gchip${scale === 'subject' ? ' subject' : ''}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><rect x="-9" y="-8" width="18" height="16" rx="2"/><text text-anchor="middle" y="4">${g}</text></g>`;
function graphInner(dataId, center, trail) {
  const D = GRAPHS[dataId], N = D.nodes;
  const adj = id => D.edges.filter(e => e.a === id || e.b === id).map(e => e.a === id ? e.b : e.a);
  const ring1 = [...new Set(adj(center))].filter(x => x !== center);
  const pos = { [center]: [G_CX, G_CY] };
  ring1.forEach((id, i) => { const t = -Math.PI / 2 + i * 2 * Math.PI / ring1.length; pos[id] = [G_CX + G_R1 * Math.cos(t) * 1.5, G_CY + G_R1 * Math.sin(t) * 0.9]; });
  const ring2 = [];
  ring1.forEach((p, i) => { const t = -Math.PI / 2 + i * 2 * Math.PI / ring1.length; const kids = [...new Set(adj(p))].filter(x => x !== center && !ring1.includes(x) && !pos[x]);
    kids.forEach((id, j) => { const a = t + (j - (kids.length - 1) / 2) * 0.55; pos[id] = [G_CX + G_R2 * Math.cos(a) * 1.25, G_CY + G_R2 * Math.sin(a) * 0.93]; ring2.push(id); }); });
  const shown = Object.keys(pos);
  const edges = D.edges.filter(e => pos[e.a] && pos[e.b]);
  const pairCount = {}; edges.forEach(e => { const k = [e.a, e.b].sort().join('|'); pairCount[k] = (pairCount[k] || 0) + 1; }); const pairSeen = {};
  const edgeSvg = edges.map(e => {
    const [ax, ay] = pos[e.a], [bx, by] = pos[e.b]; const dx = bx - ax, dy = by - ay, len = Math.hypot(dx, dy) || 1, ux = dx / len, uy = dy / len, nx = -uy, ny = ux;
    const k = [e.a, e.b].sort().join('|'); const idx = pairSeen[k] = (pairSeen[k] || 0) + 1; const off = (idx - 1 - (pairCount[k] - 1) / 2) * 26; const side = off === 0 ? (ny < 0 ? 1 : -1) : Math.sign(off);   // a lone label sits above its line; parallel lines carry theirs on their outer sides
    const ra = (e.a === center ? 30 : G_NR) + 3, rb = (e.b === center ? 30 : G_NR) + 3;
    const x1 = ax + ux * ra + nx * off, y1 = ay + uy * ra + ny * off, x2 = bx - ux * rb + nx * off, y2 = by - uy * rb + ny * off;
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    const rk = id => id === center ? 0 : ring1.includes(id) ? 1 : 2;   // the label sits nearer the end farther from the center, where lines do not converge; not under a name
    const f = rk(e.a) < rk(e.b) ? (uy < -0.6 ? 0.5 : 0.66) : rk(e.a) > rk(e.b) ? (uy > 0.6 ? 0.5 : 0.34) : 0.5;
    const px = x1 + (x2 - x1) * f, py = y1 + (y2 - y1) * f, ldy = ny * side * 14, ldx = nx * side * 14;
    const vert = Math.abs(nx) > 0.6, anchor = vert ? (ldx > 0 ? 'start' : 'end') : 'middle';
    const lx = px + ldx * (vert ? 1.15 : 1), ly = py + (vert ? 4 : ldy + (ldy > 0 ? 7 : 0));
    const line = `x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}"`;
    const kw = KINDS[e.kind].word; const scale = e.kind === 'same' ? 'subject' : 'connection';
    const tip = `<b>${esc(kw)}</b>: <span class=mk-data>${esc(N[e.a].n)}</span> → <span class=mk-data>${esc(e.w)}</span> → <span class=mk-data>${esc(N[e.b].n)}</span> · ${scale === 'subject' ? 'subject match' : 'connection'} ${e.g} · <span class=mk-data>${esc(e.cite)}</span>.` + `<span class=more>${e.kind === 'lead' ? GRAPH_WORDS.lead : esc(GRAPH_WORDS.gradeEdge)}</span>`;   // the names, the step and its citation are the record's: data
    return `<g class="edge" tabindex="0" data-tip="${esc(tip)}"><line class="hit" ${line}/><line class="e e-${e.kind}" ${line}/>${e.kind === 'money' ? `<line class="e e-money-in" ${line}/>` : ''}<text class="w${e.kind === 'lead' ? ' lead' : ''}" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anchor}">${esc(e.w)}${e.kind === 'same' ? ' =' : ''}</text>${gchip(mx, my, e.g, scale)}</g>`;
  }).join('');
  const nodeSvg = shown.map(id => { const n = N[id], [x, y] = pos[id], c = id === center, r = c ? 30 : G_NR, lim = D.limit.includes(id) && !c;
    const tip = `<b>${esc(n.n)}</b> · ${NODE_KIND[n.k]}${n.sub ? ' · <span class=mk-data>' + esc(n.sub) + '</span>' : ''}${c ? ` · ${GRAPH_WORDS.center}` : ''}${lim ? `<br><b>${GRAPH_WORDS.limit}</b>: ${GRAPH_WORDS.limitMeans}` : ''}${c ? '' : `<span class=more>${GRAPH_WORDS.click}</span>`}`;
    const name = n.n.length > 26 ? n.n.slice(0, 25) + '…' : n.n;
    return `<g class="node${c ? ' center' : ''}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})" tabindex="0" role="button" aria-label="${esc(n.n)}, ${NODE_KIND[n.k]}${c ? ', the center' : ''}" data-tip="${esc(tip)}" onclick="window.CS_GRAPH.go(this,'${id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();window.CS_GRAPH.go(this,'${id}')}">${nodeShape(n.k, r)}${lim ? `<circle class="lim" r="${r + 7}"/>` : ''}<text class="n" text-anchor="middle" y="${r + 15}">${esc(name)}</text><text text-anchor="middle" y="${r + 28}">${NODE_KIND[n.k]}</text>${lim ? `<text class="lim" text-anchor="middle" y="${r + 41}">${GRAPH_WORDS.limit.toLowerCase()}</text>` : ''}</g>`; }).join('');
  const trailHtml = `<div class="mk-trail"><span class="k" data-tip="<b>The trail</b>: ${esc(GRAPH_WORDS.trail)}">Trail</span>${trail.map((id, i) => `<button type="button" class="mk-trailbtn${i === trail.length - 1 ? ' now' : ''}" data-tip="<b>${esc(N[id].n)}</b> · ${NODE_KIND[N[id].k]}${i === trail.length - 1 ? ' · the center now' : `<span class=more>Click to make it the center again.</span>`}" onclick="window.CS_GRAPH.go(this,'${id}')">${esc(N[id].n)}</button>`).join('<span class="arr" aria-hidden="true">→</span>')}</div>`;
  const legendLine = k => k === 'money' ? `<line class="e e-money" x1="1" y1="6" x2="35" y2="6"/><line class="e e-money-in" x1="1" y1="6" x2="35" y2="6"/>` : `<line class="e e-${k}" x1="1" y1="6" x2="35" y2="6"/>`;
  const legend = `<div class="mk-glegend" aria-label="What the lines mean">${Object.entries(KINDS).map(([k, v]) => `<span class="li" data-tip="<b>${esc(v.word)}</b>: ${esc(v.means)}"><svg viewBox="0 0 36 12" aria-hidden="true">${legendLine(k)}</svg>${esc(v.word)}${k === 'lead' ? ' · a lead' : ''}</span>`).join('')}<span class="li" data-tip="<b>The letter on a line</b>: ${esc(GRAPH_WORDS.grade)}"><svg viewBox="0 0 36 12" aria-hidden="true"><g class="gchip" transform="translate(18 6)"><rect x="-8" y="-6" width="16" height="12" rx="2"/><text text-anchor="middle" y="3.5" style="font-size:9px">B</text></g></svg>the step's grade</span><span class="li" data-tip="<b>${GRAPH_WORDS.limit}</b>: ${esc(GRAPH_WORDS.limitMeans)}"><svg viewBox="0 0 36 12" aria-hidden="true"><circle class="node-lim" cx="18" cy="6" r="5"/></svg>${GRAPH_WORDS.limit}</span></div>`;
  return `${trailHtml}<div class="gwrap"><svg class="g" viewBox="0 0 ${G_W} ${G_H}" role="group" aria-label="Connections from ${esc(N[center].n)}: ${shown.length - 1} things joined to it by ${edges.length} steps">${edgeSvg}${nodeSvg}</svg></div>${legend}`;
}
const graph = (gid, dataId, center) => `<div class="mk-graph" id="${gid}" data-graph="${dataId}" data-center="${center}" data-trail="${center}">${graphInner(dataId, center, [center])}</div>`;
const CS_GRAPH = { go(el, id) { const g = el.closest('.mk-graph'); if (!g) return; const trail = g.dataset.trail.split(','); const i = trail.indexOf(id); const t = i >= 0 ? trail.slice(0, i + 1) : trail.concat(id);
  g.dataset.center = id; g.dataset.trail = t.join(','); g.innerHTML = graphInner(g.dataset.graph, id, t); if (typeof window !== 'undefined' && window.CS_TIPFIX) window.CS_TIPFIX(g); const c = g.querySelector('.node.center'); if (c && c.focus) c.focus({ preventScroll: true }); } };
if (typeof window !== 'undefined') window.CS_GRAPH = CS_GRAPH;

